</script>

<template>



          <section v-if="activeSection === 'evaluations'" class="evaluation-page">
          <div class="evaluation-toolbar"><div class="evaluation-tabs"><button :class="{ active: evaluationTab === 'overview' }" @click="selectEvaluationTab('overview')">测评总览</button><button :class="{ active: evaluationTab === 'datasets' }" @click="selectEvaluationTab('datasets')">测评集</button><button :class="{ active: evaluationTab === 'config' }" @click="selectEvaluationTab('config')">评测配置</button><button :class="{ active: evaluationTab === 'agent' }" @click="selectEvaluationTab('agent')">Agent 测评</button><button v-for="tool in [{ id: 'rag', label: 'RAG 评测' }, { id: 'bird', label: 'BIRD SQL' }, { id: 'load', label: '并发压测' }]" :key="tool.id" :class="{ active: evaluationTab === tool.id }" @click="selectEvaluationTab(tool.id)">{{ tool.label }}</button><button :class="{ active: evaluationTab === 'reports' }" @click="selectEvaluationTab('reports')">历史报告</button></div><button v-if="!['rag', 'bird', 'load', 'agent'].includes(evaluationTab)" class="button button-primary" :disabled="evalRunBusy" @click="runEvaluation"><Play :size="14" />{{ evalRunBusy ? '测评进行中…' : '运行测评' }}</button><span v-if="evalProgress" class="evaluation-progress">{{ evalProgress }}</span></div>
