          <section v-else-if="evaluationTab === 'config'" class="harness-panel evaluation-subpage"><div class="harness-panel-heading"><div><h3>评测配置</h3></div><button class="button button-primary" @click="saveEvalConfig"><Check :size="14" />保存配置</button></div><div class="evaluation-config-list"><label v-for="dimension in dimensionOptions" :key="dimension.label"><input type="checkbox" :checked="dimension.enabled" @change="toggleDimension(dimension.label, $event.target.checked)" /> <span><strong>{{ dimension.label }}</strong></span><em>{{ dimension.enabled ? '已启用' : '已停用' }}</em></label></div><div class="release-gate-fields"><strong>质量门禁</strong><div v-for="(gate, index) in evaluationConfig.gates" :key="index" class="harness-detail-actions"><input v-model="gate.label" type="text" placeholder="门禁名称" aria-label="门禁名称" /><select v-model="gate.metric" aria-label="判定指标"><option v-for="option in gateMetricOptions" :key="option.value" :value="option.value">{{ option.label }}</option></select><select v-model="gate.op" aria-label="比较符"><option v-for="option in gateOpOptions" :key="option.value" :value="option.value">{{ option.label }}</option></select><input v-model.number="gate.value" type="number" step="any" aria-label="阈值" /><button class="text-action danger" type="button" @click="removeEvalGate(index)">删除</button></div><div v-if="!(evaluationConfig.gates || []).length" class="ui-empty"><span>暂无门禁配置</span></div><div class="harness-detail-actions"><button class="button button-subtle" type="button" @click="addEvalGate"><Plus :size="14" />新增门禁</button></div></div></section>
